using System;using System.Collections.Generic;using UnityEngine;
public partial class DungeonPrototype {
 string cityTravelGroupId="";Vector2 cityMenuScroll;
 CityDungeonDestination CityTravelGroup {get{return City==null||City.story==null?null:Array.Find(City.story.destinations,g=>g!=null&&g.id==cityTravelGroupId);}}
 List<TransferNodeDefinition> CityGroupNodes(CityDungeonDestination group){var found=new Dictionary<string,TransferNodeDefinition>();if(group==null||group.map==null)return new List<TransferNodeDefinition>();
 if(group.includeLegacyNodes&&RefugeSettings.Current!=null)foreach(var node in RefugeSettings.Current.nodes)if(node!=null&&group.map.IsFloor(node.cell)&&!group.map.disabledLegacyObjects.Contains(node.id)&&refuge.unlockedNodes.Contains(node.id))found[node.id]=node;
 if(group.map.entities!=null)foreach(var entity in group.map.entities.objects)if(entity!=null&&entity.kind==DungeonEntityKind.Teleport&&group.map.IsFloor(entity.cell)&&refuge.unlockedNodes.Contains(entity.id))found[entity.id]=new TransferNodeDefinition{id=entity.id,displayName=entity.displayName,cell=entity.cell,arrivalHeading=entity.heading};
 var nodes=new List<TransferNodeDefinition>();if(group.allowEntryWithoutNode)nodes.Add(new TransferNodeDefinition{id="entry:"+group.id,displayName=group.entryNodeName,cell=group.map.startCell,arrivalHeading=group.map.startHeading});nodes.AddRange(found.Values);return nodes;}
 string[] CityTravelMenuLabels(){var labels=new List<string>();var group=CityTravelGroup;if(group==null){foreach(var route in CityDungeonDestinations())labels.Add(route.displayName);labels.Add(City.texts.back);}else{foreach(var node in CityGroupNodes(group))labels.Add(node.displayName);labels.Add("Volver a los dungeons");}return labels.ToArray();}
 bool CityTravelBack(){if(string.IsNullOrEmpty(cityTravelGroupId))return false;cityTravelGroupId="";cityServiceSelection=0;cityMenuScroll=Vector2.zero;return true;}
 void ExecuteCityTravelMenu(int index){var labels=CityTravelMenuLabels();if(index<0||index>=labels.Length)return;if(index==labels.Length-1){if(!CityTravelBack())LeaveCityLocation();return;}var group=CityTravelGroup;if(group==null){var groups=CityDungeonDestinations();if(index<groups.Count){cityTravelGroupId=groups[index].id;cityServiceSelection=0;cityMenuScroll=Vector2.zero;DungeonAudio.Play(DungeonAudio.Cue.Confirm);}return;}var nodes=CityGroupNodes(group);if(index>=nodes.Count)return;var node=nodes[index];if(!group.map.IsFloor(node.cell))return;bool first;var data=DungeonMapPersistence.ForTravel(CaptureCityModelSave(),group.map,node.cell,node.arrivalHeading,out first);data.city.inCity=false;data.city.locationId="";DigitalKingdomTransit.Explore(data,group.map,group.scenePath,City,first);}
 void EnsureCitySelectionVisible(int selected){float scale=Mathf.Min(Screen.width/1280f,Screen.height/720f),height=Screen.height/scale-285;float top=selected*65;if(top<cityMenuScroll.y)cityMenuScroll.y=top;else if(top+55>cityMenuScroll.y+height)cityMenuScroll.y=top+55-height;}
}
